#include <stdio.h>

/* menuValido pede uma opcao de 1 a 3 e repete enquanto a resposta nao serve;
   depois anuncia a opcao aceita.
   op ja nasce com 1 (uma opcao valida) de proposito: no laco desta aula o
   corpo roda ANTES da primeira pergunta, e o valor inicial nao atrapalha.
   A linha do anuncio ja esta escrita — falta o laco. */
void menuValido(void) {
    int op = 1;

    /* escreva aqui o do..while: imprima "escolha 1, 2 ou 3", leia a opcao
       com scanf, e repita enquanto op <= 0 || op >= 4 */

    printf("opcao %d aceita\n", op);
}

