#include <stdio.h>

/* teste do desafio menu-valido — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Cada cenario escreve num arquivo as opcoes que a pessoa "digitaria",
   aponta o stdin para esse arquivo (freopen), captura o stdout no proprio
   teste e le as linhas de volta. Os nomes dos arquivos temporarios sao POR
   CENARIO. Nunca ha fclose de stdin/stdout — so fflush — para o proximo
   freopen ficar legal (C11 7.21.4).
   O cenario de UMA opcao valida e o que separa do..while de while: com op
   nascendo em 1, um while na frente nao imprimiria pedido nenhum. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void menuValido(void);

SM_TEST(duas_recusas_e_a_opcao_dois) {
    /* a pessoa digita 9 (alto), 0 (baixo) e 2 (valido) */
    FILE *e = fopen("sm_entrada_1.tmp", "w");
    fprintf(e, "9 0 2\n");
    fclose(e);
    freopen("sm_entrada_1.tmp", "r", stdin);

    /* captura: o stdout vira o arquivo sm_saida_1.tmp */
    freopen("sm_saida_1.tmp", "w", stdout);
    menuValido();
    fflush(stdout);

