#include <stdio.h>

void menuValido(void) {
    int op = 1;

    do {
        printf("escolha 1, 2 ou 3\n");
        scanf("%d", &op);
    } while (op <= 0 || op >= 4);

    printf("opcao %d aceita\n", op);
}
